{"implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    min_sum = sum(s['minimum'] for s in segments)
    cap_sum = sum(s['capacity'] for s in segments)
    if budget < min_sum or budget > cap_sum:
        raise ValueError('Budget out of feasible range')
    allocations = [s['minimum'] for s in segments]
    remaining = budget - min_sum
    while remaining > 0:
        best_score = None
        best_idx = None
        for i, s in enumerate(segments):
            if allocations[i] >= s['capacity']:
                continue
            next_pos = allocations[i] + 1
            score = s['importance'] / next_pos
            if best_score is None or score > best_score or (score == best_score and i < best_idx):
                best_score = score
                best_idx = i
        if best_idx is None:
            raise ValueError('Cannot allocate all tokens')
        allocations[best_idx] += 1
        remaining -= 1
    result = {
        'allocations': [{'name': s['name'], 'allocation': allocations[i]} for i, s in enumerate(segments)],
        'name_mapping': {s['name']: allocations[i] for i, s in enumerate(segments)},
        'total_allocated': budget
    }
    return result"}
